import {hireCost,WAGE,PAY_PERIOD,MARKET_PRICES,available,activeWorkers,COUNTRIES,RESOURCES,TECHS,PRODUCTS,PATENTS,newGame,rate,capacity,upgradeCost,unlocked,researchTime,productTime,salePrice,affordable,advance,act,validateSave} from './engine.js';
const $=s=>document.querySelector(s),KEY='arsenal.save.v1';
let state=null,view='harvest',selected='fr',screen='title',last=Date.now(),saved=true,toastTimer;
const fmt=n=>Math.floor(n).toLocaleString('fr-FR');
const money=n=>n.toLocaleString('fr-FR',{maximumFractionDigits:2});
const compact=n=>n>=100000?n.toLocaleString('fr-FR',{notation:'compact',maximumFractionDigits:1}):fmt(n);
const dec=n=>n.toLocaleString('fr-FR',{maximumFractionDigits:1});
const clock=n=>`${Math.floor(Math.max(0,n)/60).toString().padStart(2,'0')}:${Math.ceil(Math.max(0,n)%60).toString().padStart(2,'0')}`;
const names={harvest:'Ressources',market:'Marché',production:'Production',research:'Recherche',patents:'Brevets',storage:'Stockage'};
const icons={harvest:'⚒',production:'⚙',research:'⚗',patents:'▤',storage:'▥'};
function notify(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function save(){if(!state)return;try{state.lastSaved=Date.now();localStorage.setItem(KEY,JSON.stringify(state));saved=true;}catch{saved=false;}}
let offlineMessage='';try{const raw=localStorage.getItem(KEY);if(raw){state=validateSave(raw);const elapsed=Math.min(28800,Math.max(0,(Date.now()-state.lastSaved)/1000));advance(state,elapsed);if(elapsed>60)offlineMessage=`Vos ateliers ont travaillé ${Math.floor(elapsed/60)} min pendant votre absence.`;save();}}catch{offlineMessage='La sauvegarde locale est illisible. Vous pouvez importer une copie ou commencer une nouvelle partie.';}
const flag=(id)=>`<span class="flag ${id}" role="img" aria-label="${COUNTRIES[id].name}">${id==='su'?`<svg class="soviet-flag" viewBox="0 0 42 27" aria-hidden="true" focusable="false"><path fill="#a5352b" d="M0 0h42v27H0z"/><g fill="#edc966"><path d="m10 2 1 3h3l-2.5 2 1 3L10 8l-2.5 2 1-3L6 5h3z"/><path d="M12 10c5 1 7 5 5 8-2 4-7 4-10 1l-3 4-2-2 4-4 2 2c3 2 7 0 7-3 0-2-1-4-3-6z"/><path d="m5 11 2-2 6 5-2 2-2-2-2 2-3-3 2-2zm4 4 2-2 7 8-2 2z"/></g></svg>`:''}</span>`;
function art(atlas,x,y,w,h,cls=''){return `<div class="art ${cls}" style="--x:${x};--y:${y};--w:${w};--h:${h};aspect-ratio:${w}/${h}"><img src="assets/${atlas}-atlas.png" alt="" draggable="false" style="width:${1536/w*100}%;left:${-x/w*100}%;top:${-y/h*100}%"></div>`;}
// Both resource atlases use transparent backgrounds and square cells.
function resourceIcon(id){
 const classic=['coal','wood','iron','rubber'].indexOf(id);
 const index=classic>=0?classic:['cotton','copper','gunpowder','shale','oil','manganese','nickel','bauxite'].indexOf(id);
 const columns=classic>=0?2:4;
 const atlas=classic>=0?'classic-resource-icons.png':'resource-icons-atlas.png';
 return `<span class="resource-icon generated-icon" aria-hidden="true"><img src="assets/${atlas}" alt="" draggable="false" style="width:${columns*100}%;height:200%;left:${-(index%columns)*100}%;top:${-Math.floor(index/columns)*100}%"></span>`;
}
function resourceScene(r){return `<div class="art resource-scene" role="img" aria-label="${r.site}"><img src="assets/resources-atlas.png" alt="" draggable="false" style="width:400%;height:300%;left:${-(r.tier%4)*100}%;top:${-Math.floor(r.tier/4)*100}%"></div>`;}
function navArt(id){const index=['harvest','market','production','research','patents','storage'].indexOf(id);return `<span class="nav-art menu-icon" aria-hidden="true"><img src="assets/menu-icons-atlas.png" alt="" draggable="false" style="left:${-(index%3)*100}%;top:${-Math.floor(index/3)*100}%"></span>`;}
function management(){return `<aside class="management"><h2>GESTION</h2><section class="management-card"><h3>RENDEMENT</h3><div class="management-stat"><span>Récolte auto / min</span><strong id="total-rate"></strong></div><div class="management-stat"><span>Salaires / min</span><strong id="total-wages"></strong></div><div class="management-stat"><span>Redevances / min</span><strong id="total-income"></strong></div><div class="management-stat"><span>Unités livrées</span><strong id="total-sold"></strong></div></section><section class="management-card"><h3>BUREAU D’ÉTUDES</h3>${art('research',1140,214,371,265)}<p id="project-status"></p><div class="meter"><i id="management-research"></i></div><button class="upgrade full" data-view="research">RECHERCHE →</button></section><section class="management-card"><h3>ARCHIVE</h3><img class="archive-illustration" src="assets/archive-library.png" alt="Bibliothèque administrative : dossiers, registres et meubles à archives" draggable="false"><div class="management-stat"><span>Technologies</span><strong>${state.tech.length} / 6</strong></div><div class="management-stat"><span>Brevets</span><strong>${state.patents.length} / 6</strong></div><button class="secondary full" data-view="storage">VOIR LES STOCKS</button></section><div class="live-dot">USINE OPÉRATIONNELLE</div></aside>`;}
function title(){screen='title';$('#app').innerHTML=`<main class="title-screen"><header class="title-top"><a class="brand" href="#">A<span class="brand-rule"></span></a><span>JEU DE GESTION INDUSTRIELLE · 1914—1945</span><span class="edition">ÉDITION PIXEL / 0.2</span></header><div class="title-body"><div class="eyebrow"><i></i> LES INDUSTRIES DE GUERRE</div><h1>ARSENAL<span>Le pouvoir se construit.</span></h1><p class="intro">Des premières mines aux grandes manufactures.<br>Récoltez, inventez, produisez. Bâtissez votre héritage industriel.</p><div class="choose-label"><span>01</span> CHOISISSEZ VOTRE NATION <small>Une sauvegarde locale par navigateur.</small></div><div class="countries">${Object.entries(COUNTRIES).map(([id,c])=>`<button class="country ${id===selected?'selected':''}" data-country="${id}" aria-pressed="${id===selected}">${flag(id)}<span class="country-name">${c.name}</span><span class="country-motto">${c.motto}</span><strong>${c.bonus}</strong><span class="check">${id===selected?'✓':'○'}</span></button>`).join('')}</div><div class="title-actions"><button class="primary start" data-action="start">FONDER MON INDUSTRIE <span>→</span></button>${state?`<button class="secondary" data-action="continue">Reprendre · ${COUNTRIES[state.country].name} →</button>`:''}</div><p class="title-note">${state?'Une nouvelle partie remplacera votre sauvegarde, après confirmation.':'Une économie à développer. Des inventions à maîtriser. À votre rythme.'}</p></div><footer class="title-footer"><span>SOLO · PROGRESSION HORS LIGNE · SANS COMPTE</span><div><button data-action="import">Importer une partie</button><a href="arsenal-source.zip" download>Code source ↗</a><span>MIT · Open source</span></div></footer></main>`;}
function goal(){if(!Object.values(state.workers).some(crew=>crew.length))return 'Récoltez du charbon, vendez-le au marché, puis engagez votre premier ouvrier pour 27 or.';const next=RESOURCES.find(r=>!state.levels[r.id]);if(next)return `Prochaine exploitation : ${next.name} · ${fmt(next.cost)} or. Gardez une réserve pour les salaires.`;if(!state.lines.some(l=>l.enabled||l.made))return 'Première mission : ouvrez Production et lancez votre atelier de fusils.';if(!state.totalSold)return 'Première livraison : vendez votre premier lot dans Production.';if(state.research)return 'Vos ingénieurs travaillent. Continuez à produire pour financer la prochaine avancée.';if(!state.tech.length)return 'Investissez vos revenus : lancez Machines à vapeur dans Recherche.';if(!state.patents.length)return 'Protégez votre première invention dans Brevets pour toucher des revenus passifs.';return 'Développez vos ateliers, financez les recherches et débloquez les blindés.';}
function shell(){screen='game';const c=COUNTRIES[state.country];$('#app').innerHTML=`<div class="game-shell"><header class="topbar"><button class="wordmark" data-action="home">ARSENAL<small>LES INDUSTRIES DE GUERRE</small></button><div class="nation-label">${flag(state.country)}<span>${c.name}<small>${c.bonus}</small></span></div><div class="resource-stocks" role="group" aria-label="Stocks de ressources">${RESOURCES.map(r=>`<div class="resource-stock" title="${r.name}">${resourceIcon(r.id)}<div><small>${r.name}</small><strong id="header-stock-${r.id}"></strong></div></div>`).join('')}</div><div class="wallet"><span>◉</span><div><small>TRÉSORERIE</small><strong id="credits"></strong></div></div><button class="icon-btn" data-action="settings" aria-label="Sauvegarde et paramètres">☰</button></header><aside class="sidebar"><div class="sidebar-label">COMPLEXE INDUSTRIEL</div><nav>${Object.entries(names).map(([id,name])=>`<button data-view="${id}" class="${view===id?'active':''}">${navArt(id)}${name}<b>${id==='research'&&state.research?'•':''}</b></button>`).join('')}</nav>${art('harvest',9,447,250,563,'sidebar-scene')}<div class="sidebar-bottom"><div class="live-dot">USINE OPÉRATIONNELLE</div><p>L’avenir appartient<br>à ceux qui le fabriquent.</p><a href="arsenal-source.zip" download>↗ Code source · MIT</a><button data-action="home">← Écran titre</button></div></aside><main class="workspace"><div class="page-heading"><div><p class="eyebrow">DIRECTION DES OPÉRATIONS / <span>${String(Object.keys(names).indexOf(view)+1).padStart(2,'0')}</span></p><h1>${({harvest:'Récolte des ressources',market:'Marché des matières premières',production:'Ateliers de production',research:'Bureau de recherche',patents:'Bureau des brevets',storage:'Magasins & réserves'})[view]}</h1></div><span class="date-badge">CAMPAGNE INDUSTRIELLE<br><strong>1936</strong></span></div><div class="mission"><span>ORDRE DU JOUR</span><p id="current-goal">${goal()}</p></div><div class="workspace-layout"><div id="content"></div>${management()}</div><footer class="game-footer"><span id="save-status">● Sauvegarde automatique</span><span>ARSENAL / VERSION 0.2 · ÉCONOMIE FICTIVE</span></footer></main></div>`;renderContent();updateNumbers();}
function workerIcon(){return `<svg class="worker-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false" shape-rendering="crispEdges"><path fill="#11170f" d="M7 1h10v2h3v7h2v3h-4v5h3v3h2v3H1v-3h2v-3h3v-5H2v-3h2V3h3z"/><path fill="#b88026" d="M7 4h10v2h2v5H5V6h2z"/><path fill="#e6bb52" d="M8 3h8v2h2v4H6V5h2z"/><path fill="#f7d986" d="M10 2h4v8h-4zM4 10h16v2H4z"/><path fill="#c69362" d="M7 13h10v4h-2v3H9v-3H7z"/><path fill="#ecc596" d="M8 13h7v3h-2v2h-3v-2H8z"/><path fill="#44392b" d="M8 13h2v1H8zM14 13h2v1h-2zM10 17h4v1h-4z"/><path fill="#687452" d="M5 19h4v2h6v-2h4v2h2v3H3v-3h2z"/><path fill="#ac9250" d="M6 19h2v5H6zM16 19h2v5h-2z"/></svg>`;}
function wageIcon(){return `<svg class="wage-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false" shape-rendering="crispEdges"><path fill="#15190f" d="M3 9h12v2h6v2h2v8h-2v2H9v-2H3v-2H1v-8h2zM9 1h10v2h2v6h-2v2H9V9H7V3h2z"/><path fill="#98702c" d="M3 12h12v8H3zM10 14h11v7H10zM9 4h10v5H9z"/><path fill="#d1a445" d="M3 10h12v3H3zM10 12h11v3H10zM9 2h10v3H9z"/><path fill="#f3d47c" d="M5 10h8v1H5zM11 12h8v1h-8zM10 2h8v1h-8zM3 15h5v1H3zM3 18h5v1H3zM11 17h9v1h-9zM11 20h9v1h-9zM10 7h8v1h-8z"/></svg>`;}
function harvest(){return `<div class="section-intro"><p>Chaque clic rapporte 1 ressource. Engagez des ouvriers pour automatiser la récolte.</p><span>12 RESSOURCES · OUVERTURE PROGRESSIVE</span></div><div class="resource-grid">${RESOURCES.map((r,i)=>{
 const open=unlocked(state,r),ready=available(state,r);
 const reason=ready?'Achetez cette exploitation pour accéder à sa ressource.':`Ouvrez d’abord : ${RESOURCES.find(x=>x.id===r.previous).name}.`;
 return `<article class="resource-card ${!open?'locked':''}"><header><h2>${resourceIcon(r.id)}${r.name}</h2><span class="level" id="level-${r.id}"></span></header>${resourceScene(r)}<div class="resource-info"><span class="serial">EXPLOITATION ${String(i+1).padStart(2,'0')}</span><p>${r.desc}</p>${!open?`<div class="lock-info">${reason}</div><button class="upgrade full" data-action="upgrade" data-id="${r.id}" id="upgrade-${r.id}"></button>`:`<div class="stock-row"><div><small>EN RÉSERVE</small><strong id="stock-${r.id}"></strong></div><span class="rate" id="rate-${r.id}"></span></div><div class="meter"><i id="bar-${r.id}"></i></div><div class="card-actions"><button class="secondary" data-action="harvest" data-id="${r.id}" id="harvest-${r.id}">Récolter +1</button><button class="upgrade" data-action="upgrade" data-id="${r.id}" id="upgrade-${r.id}"></button></div><section class="worker-panel" aria-label="Ouvriers et salaires"><div class="worker-counter" id="crew-${r.id}" role="group" aria-label="Ouvriers engagés">${workerIcon()}<strong id="workers-${r.id}">0</strong><span class="worker-status" id="worker-status-${r.id}" role="img"></span></div><div class="worker-controls"><button class="secondary" data-action="dismiss" data-id="${r.id}" id="dismiss-${r.id}" aria-label="Libérer un ouvrier — ${r.name}" title="Libérer un ouvrier ; le salaire déjà payé n’est pas remboursé">−</button><button class="upgrade" data-action="hire" data-id="${r.id}" id="hire-${r.id}" aria-label="Engager un ouvrier — ${r.name}, ${hireCost(state,r)+WAGE} or" title="Embauche : ${hireCost(state,r)} or + ${WAGE} or pour la première minute ; embauche ×1,3 par ouvrier supplémentaire">+</button></div><div class="worker-wages" id="wages-${r.id}" role="group" title="${WAGE} or par ouvrier et par minute, payés d’avance, même hors ligne ou si le stock est plein. Sans or, les ouvriers se mettent en pause.">${wageIcon()}<strong id="payroll-${r.id}">0</strong><small>/ min</small></div></section>`}</div></article>`;
 }).join('')}</div>`;}
function market(){return `<div class="section-intro"><p>Vendez vos matières premières pour financer vos ouvriers et de nouvelles exploitations.</p><span>PRIX FIXES · PAIEMENT IMMÉDIAT</span></div><div class="market-grid">${RESOURCES.map(r=>`<article class="storage-panel market-card"><h2 class="resource-name">${resourceIcon(r.id)}${r.name}</h2><p class="market-price">${money(MARKET_PRICES[r.id])} or <small>/ unité</small></p><p>En réserve : <strong id="stock-${r.id}"></strong></p><div class="market-actions"><button class="secondary" data-action="sell-resource" data-id="${r.id}" id="sell-resource-${r.id}">Vendre 1 · ${money(MARKET_PRICES[r.id])} or</button><button class="secondary" data-action="sell-ten" data-id="${r.id}" id="sell-ten-${r.id}">Vendre 10 · ${money(MARKET_PRICES[r.id]*10)} or</button><button class="upgrade" data-action="sell-all" data-id="${r.id}" id="sell-all-${r.id}"></button></div></article>`).join('')}</div>`;}
function vehicle(id){const col=PRODUCTS.findIndex(p=>p.id===id),row=({fr:0,us:0,de:1,su:2})[state.country];return `<div class="equipment-sprite" role="img" aria-label="${COUNTRIES[state.country].units[col]} en pixel art" style="background-position:${col*50}% ${row*50}%"></div>`;}
function production(){return `<div class="section-intro"><p>Transformez vos matières en équipements. Vendez les lots pour financer votre expansion.</p></div><div class="production-list">${PRODUCTS.map((p,i)=>{let l=state.lines[i],lock=p.unlock&&!state.tech.includes(p.unlock);return `<article class="production-card ${lock?'locked':''}"><div class="product-art"><span class="serial">ATELIER 0${i+1} / ${p.kind}</span>${vehicle(p.id)}<span class="blueprint-label">PLAN D’ENSEMBLE · ${COUNTRIES[state.country].icon} / 0${i+1}</span></div><div class="product-details"><div class="product-heading"><h2>${COUNTRIES[state.country].units[i]}</h2><span id="status-${p.id}" class="status"></span></div><div class="recipe">${Object.entries(p.recipe).map(([k,v])=>`<span>${RESOURCES.find(r=>r.id===k).icon} ${v} ${RESOURCES.find(r=>r.id===k).name}</span>`).join('')}</div>${lock?`<p>Recherche requise : ${TECHS.find(t=>t.id===p.unlock).name}</p><button class="secondary" data-view="research">Ouvrir la recherche →</button>`:`<div class="production-stats"><span>${dec(productTime(state,p))} s / unité</span><span>${fmt(salePrice(state,p))} or / unité</span><span id="made-${p.id}"></span></div><div class="meter"><i id="progress-${p.id}"></i></div><div class="card-actions"><button class="secondary" data-action="toggle" data-id="${p.id}" id="toggle-${p.id}"></button><button class="upgrade" data-action="sell" data-id="${p.id}" id="sell-${p.id}"></button></div>`}</div></article>`;}).join('')}</div>`;}
function research(){return `<div class="section-intro"><p>Un bureau, six avancées. Chaque invention transforme votre industrie.</p><span>UN PROJET À LA FOIS</span></div><div class="tech-grid">${TECHS.map((t,i)=>{let done=state.tech.includes(t.id),running=state.research?.id===t.id,ready=t.requires.every(k=>state.tech.includes(k));return `<article class="tech-card ${done?'completed':''} ${!ready?'locked':''}">${art('research',t.x,t.y,t.w,t.h)}<div class="resource-info"><span class="serial">DOSSIER R–0${i+1} / ${done?'VALIDÉ':running?'EN COURS':'RECHERCHE'}</span><h2>${t.name}</h2><p>${t.desc}</p><div class="tech-requirements">${t.requires.length?'Prérequis : '+t.requires.map(k=>TECHS.find(x=>x.id===k).name).join(', '):'Aucun prérequis'}</div>${done?'<div class="done-label">✓ Technologie maîtrisée</div>':running?`<div class="meter"><i id="research-bar"></i></div><div class="research-time" id="research-time"></div>`:`<button class="upgrade full" data-action="research" data-id="${t.id}" id="research-${t.id}" ${!ready?'disabled':''}>Rechercher · ${fmt(t.cost)} ◉ <small>${clock(researchTime(state,t))}</small></button>`}</div></article>`;}).join('')}</div>`;}
function patentDrawing(i){const drawings=[[305,304,413,130],[305,647,413,125],[754,304,413,130],[754,648,413,125],[305,647,413,125],[305,304,413,130]];return art('patents',...drawings[i],'patent-drawing');}
function patents(){return `<div class="section-intro"><p>Déposez vos inventions pour accorder des licences et toucher des redevances automatiques.</p><span id="patent-rate"></span></div><div class="patent-grid">${PATENTS.map((p,i)=>{const owns=state.patents.includes(p.id),ready=state.tech.includes(p.id);return `<article class="patent-card ${!ready?'patent-locked':''}"><div class="paper-top"><span>RÉPUBLIQUE INDUSTRIELLE</span><span>N° 00${42+i}</span></div><h2>${p.name}</h2>${patentDrawing(i)}<p>Certificat d’exploitation industrielle</p><div class="stamp ${owns?'owned':''}">${owns?'DÉPOSÉ':ready?'À DÉPOSER':'VERROUILLÉ'}</div><div class="patent-benefit">Redevances <strong>+ ${dec(p.income*60)} ◉ / min</strong></div>${owns?'<span class="license-active">✓ Licence active · revenus automatiques</span>':ready?`<button class="paper-button" data-action="patent" data-id="${p.id}" id="patent-${p.id}">Déposer le brevet · ${fmt(p.cost)} ◉</button>`:`<button class="paper-button" data-view="research">Recherche requise →</button>`}</article>`;}).join('')}</div>`;}
function storage(){return `<div class="section-intro"><p>Vos matières premières et vos équipements disponibles.</p><span>CAPACITÉ ADAPTÉE À CHAQUE EXPLOITATION</span></div><section class="storage-panel"><h2>Registre des matières premières</h2>${RESOURCES.map(r=>`<div class="inventory-row"><span class="resource-name">${resourceIcon(r.id)}${r.name}</span><div class="meter"><i id="bar-${r.id}"></i></div><strong id="stock-${r.id}"></strong><small id="rate-${r.id}"></small></div>`).join('')}</section><section class="storage-panel"><h2>Équipements prêts à livrer</h2>${PRODUCTS.map((p,i)=>`<div class="inventory-row"><span>${COUNTRIES[state.country].units[i]}</span><strong id="warehouse-${p.id}"></strong><button class="upgrade" data-action="sell" data-id="${p.id}" id="sell-${p.id}"></button></div>`).join('')}</section>`;}
function renderContent(){$('#content').innerHTML=({harvest,market,production,research,patents,storage})[view]();}
function text(id,value){const el=document.getElementById(id);if(el)el.textContent=value;}
function width(id,v){const el=document.getElementById(id);if(el)el.style.width=Math.min(100,Math.max(0,v))+'%';}
function disable(id,value){const el=document.getElementById(id);if(el)el.disabled=value;}
function updateNumbers(){if(screen!=='game')return;text('credits',money(state.credits)+' or');text('current-goal',goal());text('total-wages',fmt(Object.values(state.workers).reduce((n,crew)=>n+crew.length*WAGE,0))+' or');text('total-rate','+ '+dec(RESOURCES.reduce((sum,r)=>sum+rate(state,r)*60,0)));text('total-income','+ '+dec(PATENTS.filter(p=>state.patents.includes(p.id)).reduce((sum,p)=>sum+p.income*60,0)));text('total-sold',fmt(state.totalSold));text('project-status',state.research?TECHS.find(t=>t.id===state.research.id).name+' · '+clock(state.research.remaining):'Ingénieurs disponibles');width('management-research',state.research?100*(1-state.research.remaining/researchTime(state,TECHS.find(t=>t.id===state.research.id))):0);text('save-status',saved?'● Sauvegarde automatique':'⚠ Sauvegarde indisponible · exportez votre partie');for(const r of RESOURCES){text('stock-'+r.id,fmt(state.resources[r.id]));const stockEl=document.getElementById('stock-'+r.id);if(stockEl)stockEl.title=`Capacité : ${fmt(capacity(state,r))}`;text('header-stock-'+r.id,compact(state.resources[r.id]));text('rate-'+r.id,`+ ${dec(rate(state,r)*60)} / min`);text('level-'+r.id,state.levels[r.id]?`NIV. ${state.levels[r.id]}`:'À OUVRIR');text('upgrade-'+r.id,`${state.levels[r.id]?'Améliorer':'Ouvrir'} · ${fmt(upgradeCost(state,r))} ◉`);disable('upgrade-'+r.id,!available(state,r)||state.levels[r.id]>=100||state.credits<upgradeCost(state,r));width('bar-'+r.id,state.resources[r.id]/capacity(state,r)*100);
 const crew=state.workers[r.id],active=activeWorkers(state,r),quantity=Math.floor(state.resources[r.id]);
 text('workers-'+r.id,crew.length);
 text('payroll-'+r.id,crew.length*WAGE);
 const crewStatus=!crew.length?'Aucun ouvrier':active<crew.length?`${active} au travail, ${crew.length-active} en pause : salaire manquant`:`${active} au travail · prochain salaire dans ${Math.ceil(Math.min(...crew))} s`;
 const statusEl=document.getElementById('worker-status-'+r.id);
 if(statusEl){statusEl.textContent=active<crew.length?'Ⅱ':'●';statusEl.dataset.state=!crew.length?'empty':active<crew.length?'paused':'active';statusEl.title=crewStatus;statusEl.setAttribute('aria-label',crewStatus);}
 const crewEl=document.getElementById('crew-'+r.id);if(crewEl){crewEl.title=crewStatus;crewEl.setAttribute('aria-label',`${crew.length} ouvrier(s) · ${crewStatus}`);}
 const wagesEl=document.getElementById('wages-'+r.id);if(wagesEl)wagesEl.setAttribute('aria-label',`Salaires : ${crew.length*WAGE} or par minute`);
 disable('harvest-'+r.id,state.resources[r.id]>=capacity(state,r));
 disable('hire-'+r.id,state.credits<hireCost(state,r)+WAGE||crew.length>=100);
 disable('dismiss-'+r.id,!crew.length);
 disable('sell-resource-'+r.id,quantity<1);disable('sell-ten-'+r.id,quantity<10);disable('sell-all-'+r.id,quantity<1);
 text('sell-all-'+r.id,`Tout vendre (${fmt(quantity)}) · ${money(quantity*MARKET_PRICES[r.id])} or`);
}
 for(const p of PRODUCTS){const l=state.lines.find(l=>l.id===p.id);text('status-'+p.id,l.enabled?(l.remaining>0?'EN PRODUCTION':affordable(state,p.recipe)?'DÉMARRAGE':'MATIÈRES MANQUANTES'):'À L’ARRÊT');text('toggle-'+p.id,l.enabled?'Ⅱ Suspendre':'▶ Lancer la production');text('sell-'+p.id,`Vendre ${l.stock} · ${fmt(l.stock*salePrice(state,p))} ◉`);disable('sell-'+p.id,!l.stock);text('made-'+p.id,`${l.made} unités fabriquées`);text('warehouse-'+p.id,`${l.stock} en stock`);width('progress-'+p.id,l.remaining>0?100*(1-l.remaining/productTime(state,p)):0);}
 for(const t of TECHS)disable('research-'+t.id,!!state.research||state.credits<t.cost||!t.requires.every(k=>state.tech.includes(k)));
 if(state.research){const t=TECHS.find(t=>t.id===state.research.id);width('research-bar',100*(1-state.research.remaining/researchTime(state,t)));text('research-time',`${clock(state.research.remaining)} · Recherche en cours`);}
 for(const p of PATENTS)disable('patent-'+p.id,state.credits<p.cost);text('patent-rate',`REDEVANCES · + ${dec(PATENTS.filter(p=>state.patents.includes(p.id)).reduce((a,p)=>a+p.income*60,0))} ◉ / MIN`);
}
function settings(){const d=document.createElement('dialog');d.innerHTML=`<form method="dialog"><div class="modal-header"><h2>Archives de l’industrie</h2><button class="icon-btn" aria-label="Fermer">×</button></div><p>Votre partie est sauvegardée dans ce navigateur. Exportez-la pour changer d’appareil ou conserver une copie.</p><div class="modal-actions"><button type="button" class="primary" data-action="export">Exporter la sauvegarde</button><button type="button" class="secondary" data-action="import">Importer une sauvegarde</button><a class="secondary" href="arsenal-source.zip" download>Télécharger le code source ↗</a></div><p class="small">Progression hors ligne limitée à 8 heures. La production consomme les ressources ; vendez vos lots pour gagner des or. Les ouvriers sont payés d’avance chaque minute, y compris hors ligne ; sans or ils se mettent en pause. Les brevets rapportent automatiquement.</p><button class="secondary full">Retour à l’usine</button></form>`;document.body.append(d);d.addEventListener('close',()=>d.remove());d.showModal();}
function download(){save();const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`arsenal-${state.country}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Sauvegarde exportée.');}
function importSave(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file||file.size>100000)throw Error();const next=validateSave(await file.text());if(state&&!confirm('Remplacer votre partie actuelle par cette sauvegarde ?'))return;state=next;advance(state,Math.max(0,(Date.now()-state.lastSaved)/1000));save();last=Date.now();document.querySelector('dialog')?.close();shell();notify('Sauvegarde restaurée.');}catch{notify('Fichier invalide : choisissez une sauvegarde Arsenal au format JSON.');}};input.click();}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.country){selected=b.dataset.country;title();return;}if(b.dataset.view){view=b.dataset.view;shell();return;}const a=b.dataset.action;if(!a)return;if(a==='start'){if(state&&!confirm('Créer une nouvelle industrie et remplacer la sauvegarde actuelle ? Pensez à l’exporter avant.'))return;state=newGame(selected);view='harvest';last=Date.now();save();shell();return;}if(a==='continue'){last=Date.now();shell();if(offlineMessage){notify(offlineMessage);offlineMessage='';}return;}if(a==='home'){save();title();return;}if(a==='settings'){settings();return;}if(a==='export'){download();return;}if(a==='import'){importSave();return;}if(state&&act(state,a,b.dataset.id)){save();if(['harvest','sell-resource','sell-ten','sell-all'].includes(a)){updateNumbers();return;}shell();if(a==='patent')notify('Brevet déposé. Les redevances sont maintenant automatiques.');}else notify('Conditions ou ressources insuffisantes.');});
setInterval(()=>{const now=Date.now();if(state){const before=state.tech.length;advance(state,(now-last)/1000);if(state.tech.length!==before){if(screen==='game')shell();notify('Recherche terminée : '+TECHS.find(t=>t.id===state.tech.at(-1)).name);}updateNumbers();}last=now;},250);
setInterval(save,5000);document.addEventListener('visibilitychange',()=>{if(document.hidden)save();});window.addEventListener('pagehide',save);title();
